package org.brightstats.stats;

import java.util.*;
import java.nio.file.*;
import com.google.gson.*;

public final class ClusterChecks {
    static int checks;static void require(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    static SemModel.Model varianceModel(double variance,boolean mean){List<SemModel.Parameter> parameters=new ArrayList<>();parameters.add(new SemModel.Parameter("Variance",List.of(new SemModel.Location(SemModel.Kind.COVARIANCE,0,0)),variance,1,1e-7,null));if(mean)parameters.add(new SemModel.Parameter("Mean",List.of(new SemModel.Location(SemModel.Kind.INTERCEPT,0,0)),.1,1));return new SemModel.Model(List.of("Y"),new int[]{0},new double[1][1],new double[][]{{variance}},new double[1],parameters);}
    static JsonObject record(double[][] data,List<String> ids,TwoLevelSem.Fit fit){Gson gson=new GsonBuilder().serializeNulls().serializeSpecialFloatingPointValues().create();JsonObject value=new JsonObject();value.add("data",gson.toJsonTree(data));value.add("ids",gson.toJsonTree(ids));value.add("fit",gson.toJsonTree(fit));return value;}
    public static void main(String[] args)throws Exception{
        Path out=Path.of(args[0]);Files.createDirectories(out);Random random=new Random(77501);int g=60,size=6;double[][] data=new double[g*size][1];List<String> ids=new ArrayList<>();for(int cluster=0;cluster<g;cluster++){double effect=Math.sqrt(.5)*random.nextGaussian();for(int i=0;i<size;i++){data[cluster*size+i][0]=.35+effect+Math.sqrt(.8)*random.nextGaussian();ids.add("Cluster "+cluster);}}
        var marginal=ClusterSem.fit(data,ids,SimulationChecks.meanModel(.1),new ClusterSem.Options(FimlSem.Options.defaults(),true,60,442),null);double mean=Arrays.stream(data).mapToDouble(row->row[0]).average().orElseThrow(),meat=0;for(int c=0;c<g;c++){double sum=0;for(int i=0;i<size;i++)sum+=data[c*size+i][0]-mean;meat+=sum*sum;}double expected=meat/(data.length*(double)data.length)*g/(g-1.0);require(Math.abs(marginal.terms().getFirst().estimate()-mean)<1e-7,"Cluster point fit retains marginal mean");require(Math.abs(marginal.clusterCovariance()[0][0]-expected)<1e-8,"Independent cluster-sum mean covariance");require(marginal.informativeClusters()==g&&marginal.successfulBootstrap()==60,"Whole-cluster bootstrap complete accounting");var again=ClusterSem.fit(data,ids,SimulationChecks.meanModel(.1),new ClusterSem.Options(FimlSem.Options.defaults(),true,60,442),null);for(int i=0;i<60;i++)require(Arrays.equals(marginal.bootstrap().get(i).estimates(),again.bootstrap().get(i).estimates()),"Reproducible whole-cluster resampling");
        var specification=new TwoLevelSem.Specification(varianceModel(.6,false),varianceModel(.4,true));var fit=TwoLevelSem.fit(data,ids,specification,FimlSem.Options.defaults());double withinSS=0,betweenSS=0;for(int c=0;c<g;c++){double average=0;for(int i=0;i<size;i++)average+=data[c*size+i][0]/size;betweenSS+=(average-mean)*(average-mean);for(int i=0;i<size;i++)withinSS+=Math.pow(data[c*size+i][0]-average,2);}double w=withinSS/(g*(size-1.0)),b=betweenSS/g-w/size;require(fit.converged()&&fit.locallyIdentified()&&!fit.boundary(),"Two-level independent mean/variances are regular");require(Math.abs(fit.estimates()[0]-w)<2e-6&&Math.abs(fit.estimates()[1]-b)<2e-6&&Math.abs(fit.estimates()[2]-mean)<2e-6,"Balanced Gaussian random-intercept closed-form ML");require(Math.abs(fit.intraclassCorrelations()[0]-b/(b+w))<2e-6,"Within/between ICC decomposition");
        var work=new TwoLevelSem.Work(data,ids,specification);double[] theta={.7,.45,.2};var evaluation=work.evaluate(theta);for(int j=0;j<theta.length;j++){double[] plus=theta.clone(),minus=theta.clone();plus[j]+=1e-5;minus[j]-=1e-5;double numeric=(work.evaluate(plus).value()-work.evaluate(minus).value())/2e-5;require(Math.abs(numeric-evaluation.gradient()[j])<1e-7,"Analytic two-level likelihood gradient");}
        List<double[]> unequalRows=new ArrayList<>();List<String> unequalIds=new ArrayList<>();for(int c=0;c<g;c++){double effect=Math.sqrt(.5)*random.nextGaussian();for(int i=0;i<3+c%8;i++){unequalRows.add(new double[]{.35+effect+Math.sqrt(.8)*random.nextGaussian()});unequalIds.add("C"+c);}}double[][] unequal=unequalRows.toArray(double[][]::new);var unequalFit=TwoLevelSem.fit(unequal,unequalIds,specification,FimlSem.Options.defaults());require(unequalFit.converged()&&unequalFit.locallyIdentified(),"Unequal cluster sizes use exact marginal likelihood");
        var withinFactor=new SemModel.Model(List.of("A","B"),new int[]{0,1},new double[2][2],new double[][]{{.9,0},{0,1.2}},new double[2],List.of(new SemModel.Parameter("Within A variance",List.of(new SemModel.Location(SemModel.Kind.COVARIANCE,0,0)),.7,1,1e-7,null),new SemModel.Parameter("Within B residual",List.of(new SemModel.Location(SemModel.Kind.COVARIANCE,1,1)),1,1,1e-7,null),new SemModel.Parameter("Within path",List.of(new SemModel.Location(SemModel.Kind.DIRECTED,1,0)),.1,1)));
        var betweenFactor=new SemModel.Model(List.of("A","B","Factor"),new int[]{0,1},new double[][]{{0,0,1},{0,0,.7},{0,0,0}},new double[][]{{0,0,0},{0,0,0},{0,0,.6}},new double[3],List.of(new SemModel.Parameter("Between factor variance",List.of(new SemModel.Location(SemModel.Kind.COVARIANCE,2,2)),.4,1,1e-7,null),new SemModel.Parameter("A mean",List.of(new SemModel.Location(SemModel.Kind.INTERCEPT,0,0)),0,1),new SemModel.Parameter("B mean",List.of(new SemModel.Location(SemModel.Kind.INTERCEPT,1,0)),0,1)));
        List<double[]> factorRows=new ArrayList<>();List<String> factorIds=new ArrayList<>();for(int c=0;c<80;c++){double effect=Math.sqrt(.6)*random.nextGaussian();for(int i=0;i<4+c%5;i++){double a=Math.sqrt(.9)*random.nextGaussian(),bValue=.3*a+Math.sqrt(1.2)*random.nextGaussian();factorRows.add(new double[]{.2+effect+a,-.1+.7*effect+bValue});factorIds.add("F"+c);}}double[][] factorData=factorRows.toArray(double[][]::new);var factorSpecification=new TwoLevelSem.Specification(withinFactor,betweenFactor);var factorFit=TwoLevelSem.fit(factorData,factorIds,factorSpecification,FimlSem.Options.defaults());require(factorFit.converged()&&factorFit.locallyIdentified()&&!factorFit.boundary(),"Rank-deficient between covariance supported as a proper factor component");var factorWork=new TwoLevelSem.Work(factorData,factorIds,factorSpecification);double[] factorTheta={.8,1.1,.2,.5,.1,-.05};var factorEvaluation=factorWork.evaluate(factorTheta);for(int j=0;j<factorTheta.length;j++){double[] plus=factorTheta.clone(),minus=factorTheta.clone();plus[j]+=1e-5;minus[j]-=1e-5;require(Math.abs((factorWork.evaluate(plus).value()-factorWork.evaluate(minus).value())/2e-5-factorEvaluation.gradient()[j])<1e-7,"Within path / between factor analytic derivative");}
        double[][] masked=Matrices.copy(data);for(int i=0;i<30;i++)masked[i][0]=Double.NaN;var missing=ClusterSem.fit(masked,ids,SimulationChecks.meanModel(.1),ClusterSem.Options.defaults(),null);require(missing.informativeClusters()==55&&missing.suppliedClusters()==60,"All-missing clusters separated from informative count");try{TwoLevelSem.fit(masked,ids,specification,FimlSem.Options.defaults());throw new AssertionError("Two-level missing data silently used");}catch(IllegalArgumentException expectedFailure){checks++;}try{new TwoLevelSem.Specification(varianceModel(1,true),varianceModel(1,true));throw new AssertionError("Within means not constrained");}catch(IllegalArgumentException expectedFailure){checks++;}
        Thread.currentThread().interrupt();try{ClusterSem.fit(data,ids,SimulationChecks.meanModel(.1),ClusterSem.Options.defaults(),null);throw new AssertionError("Cluster cancellation ignored");}catch(java.util.concurrent.CancellationException expectedFailure){checks++;}finally{Thread.interrupted();}Thread.currentThread().interrupt();try{TwoLevelSem.fit(data,ids,specification,FimlSem.Options.defaults());throw new AssertionError("Two-level cancellation ignored");}catch(java.util.concurrent.CancellationException expectedFailure){checks++;}finally{Thread.interrupted();}
        var gson=new GsonBuilder().serializeNulls().serializeSpecialFloatingPointValues().setPrettyPrinting().create();JsonObject result=new JsonObject();result.add("balanced",record(data,ids,fit));result.getAsJsonObject("balanced").add("cluster",gson.toJsonTree(marginal));result.add("unequal",record(unequal,unequalIds,unequalFit));result.add("factor",record(factorData,factorIds,factorFit));result.addProperty("checks",checks);Files.writeString(out.resolve("cases.json"),gson.toJson(result));System.out.println("Cluster/two-level checks: "+checks);
    }
}
